import{_ as r,o as a,c as s,a2 as o}from"./chunks/framework.BS0bAV7E.js";const m=JSON.parse('{"title":"Ring 3: syscalls, ELF loading, processes","description":"","frontmatter":{},"headers":[],"relativePath":"arch/syscall-ring3.md","filePath":"arch/syscall-ring3.md"}'),l={name:"arch/syscall-ring3.md"};function c(t,e,d,n,i,h){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="ring-3-syscalls-elf-loading-processes" tabindex="-1">Ring 3: syscalls, ELF loading, processes <a class="header-anchor" href="#ring-3-syscalls-elf-loading-processes" aria-label="Permalink to &quot;Ring 3: syscalls, ELF loading, processes&quot;">​</a></h1><h2 id="the-syscall-abi" tabindex="-1">The syscall ABI <a class="header-anchor" href="#the-syscall-abi" aria-label="Permalink to &quot;The syscall ABI&quot;">​</a></h2><p><code>kernel/core/core_syscall.h</code>: <code>rax</code> = syscall number, <code>rdi</code>/<code>rsi</code>/ <code>rdx</code>/<code>r10</code> = arguments, <code>rax</code> = result (&gt;= 0 success, &lt; 0 error). 53 syscall numbers are defined (verify: <code>grep -c &#39;#define SYS_&#39; kernel/core/core_syscall.h</code>).</p><h2 id="user-programs" tabindex="-1">User programs <a class="header-anchor" href="#user-programs" aria-label="Permalink to &quot;User programs&quot;">​</a></h2><p><code>kernel/core/core_usermode.c</code> + assembly trampolines: ring-3 entry, fork (<code>arch_enter_ring3_fork.S</code>), the ELF loader, the process table, signals. <code>userprogs/</code> ships the test fleet - hello, fork, exec, pipe, signal, select, mmap variants, and the dynamic-linking family.</p><h2 id="dynamic-linking-a-real-in-tree-ld-so" tabindex="-1">Dynamic linking - a real in-tree ld.so <a class="header-anchor" href="#dynamic-linking-a-real-in-tree-ld-so" aria-label="Permalink to &quot;Dynamic linking - a real in-tree ld.so&quot;">​</a></h2><p><code>libs/ld_so.c</code> is a shared-object loader: <code>run so_test</code>, <code>run dlsym_test</code>, <code>run pie_test</code>, <code>run reloc_test</code>, <code>run dyn_hello</code>, <code>run g7mmap</code> all exercise it. L1 modules load the same way at runtime - see <a href="./../l1/solib-loader.html">../l1/solib-loader.md</a>.</p><h2 id="how-a-user-program-runs" tabindex="-1">How a user program runs <a class="header-anchor" href="#how-a-user-program-runs" aria-label="Permalink to &quot;How a user program runs&quot;">​</a></h2><p><code>run &lt;name&gt;</code> looks up the embedded program header (built from <code>userprogs/</code> at kernel build time through <code>tools/embed_userprog.py</code> / <code>tools/build_c_userprog.py</code>) or a file on a mounted filesystem, loads the ELF, and enters ring 3. The program syscalls back for I/O; when it exits, its slot returns to the process table.</p><h2 id="faults-from-ring-3" tabindex="-1">Faults from ring 3 <a class="header-anchor" href="#faults-from-ring-3" aria-label="Permalink to &quot;Faults from ring 3&quot;">​</a></h2><p>A user-mode #PF that is not growth escalates to a per-process kill (not a kernel panic); a user-mode #DE/#UD likewise. The E2E suites cover all of this (<code>int3_user</code> runs from the shell as a test).</p>',11)])])}const p=r(l,[["render",c]]);export{m as __pageData,p as default};
